mapper.select:
select virtualWarehouseId,virtualWarehouseName,disabled from (select vw.id virtualWarehouseId,vw.name virtualWarehouseName,vw.disabled from virtual_warehouse_relation vwr inner join virtual_warehouse vw on vwr.virtual_warehouse_id=vw.id and vw.is_deleted=false and vw.disabled=false where vwr.is_deleted=false and vwr.disabled=false
and vwr.warehouse_id = #{params.warehouseId}
group by vw.id order by vw.id) virtualWarehouse

select vwr.warehouse_id as warehouseId, vw.id as virtualWarehouseId, vw.name as virtualWarehouseName, vw.disabled, vwc.relation_id as relationId, vwc.dict_platform as dictPlatform, vwc.type, from virtual_warehouse_relation vwr inner join virtual_warehouse vw on vwr.virtual_warehouse_id=vw.id and vw.is_deleted=false and vw.disabled=false inner join virtual_warehouse_channel vwc on vw.id = vwc.virtual_warehouse_id and vwc.is_deleted =false where vwr.is_deleted = false and vwr.disabled = false and vwr.warehouse_id in
#{item}
order by vw.id
